package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.server.level.*;import net.minecraft.world.item.*;import net.minecraft.world.phys.*;import java.util.*;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)
public final class NtServer {
 private static final class Draft {int sequence=-1;long tick=-1000;String dimension="";List<Vec3> accepted=List.of();NtGeometry.Plan plan;UUID id;long revision;}
 private static final Map<UUID,Draft> DRAFTS=new HashMap<>();private static final Map<UUID,Map<UUID,Long>> WATCHED=new HashMap<>();private static final Map<UUID,String> DIMENSIONS=new HashMap<>();
 public static void request(ServerPlayer player,NtRequest m){
  if(!player.isAlive()||player.isSpectator()||!player.mayBuild()||!player.getMainHandItem().is(AddonItems.NT01_BUILDER.get()))return;
  var level=player.serverLevel();String dimension=level.dimension().location().toString();var draft=DRAFTS.computeIfAbsent(player.getUUID(),x->new Draft());long now=level.getGameTime();if(!draft.dimension.equals(dimension)||now-draft.tick>6000){draft.accepted=List.of();draft.sequence=-1;draft.plan=null;draft.dimension=dimension;}
  if(now-draft.tick<8){result(player,m,"Please wait for the current builder request.");return;}draft.tick=now;
  var store=NtStore.get(level);NtTunnel before=m.id()==null?null:store.tunnels.get(m.id());
  try{
   if(m.action()==NtRequest.UNDO){undo(player,store,m);return;}
   if(m.id()!=null&&(before==null||!owns(player,before)||before.revision()!=m.revision()))throw new IllegalArgumentException("Tunnel changed, is missing, or belongs to another player. Reload it before editing.");
   if(m.action()==NtRequest.REMOVE){if(before==null||distance(player,before)>64)throw new IllegalArgumentException("Move within 64 blocks of your tunnel to remove it.");store.remove(before.id());store.undo.entrySet().removeIf(e->e.getValue().id().equals(before.id()));store.setDirty();refund(player,new int[]{before.iron(),before.string(),before.chains()});result(player,m,"Tunnel removed; paid materials returned once.");return;}
   for(Vec3 at:m.points()){boolean known=draft.accepted.stream().anyMatch(p->p.distanceToSqr(at)<1e-12)||before!=null&&before.plan().points().stream().anyMatch(p->p.distanceToSqr(at)<1e-12);if(!known&&physical(player).distanceToSqr(at)>16*16)throw new IllegalArgumentException("Walk within 16 blocks of every new or moved route point.");}
   if(m.action()==NtRequest.PREVIEW&&m.points().size()==1){draft.accepted=List.copyOf(m.points());draft.sequence=m.sequence();draft.plan=null;AddonNetwork.sendNt(player,new NtReply(NtReply.PREVIEW,m.sequence(),m.id(),dimension,"First point accepted. Add another point.",null));return;}
   if(m.points().size()<2)throw new IllegalArgumentException("Add at least two route points.");
   if(m.action()==NtRequest.BUILD&&(draft.plan==null||m.sequence()!=draft.sequence||!Objects.equals(m.id(),draft.id)||m.revision()!=draft.revision||!draft.plan.fingerprint().equals(m.fingerprint())))throw new IllegalArgumentException("Wait for an up-to-date server preview before building.");
   var plan=NtTerrain.plan(player,m.points(),m.settings());List<String> errors=new ArrayList<>(plan.errors());if(store.overlaps(m.id(),plan))NtTerrain.add(errors,"The new net intersects an existing NT-01 tunnel. Load that tunnel to extend it.");if(store.faceCount()-(before==null?0:NtGeometry.panels(new NtGeometry.Path(before.plan().points(),before.plan().settings()),before.plan()).size()*2)+NtGeometry.panels(new NtGeometry.Path(plan.points(),plan.settings()),plan).size()*2>160000)NtTerrain.add(errors,"This dimension's tunnel geometry budget is full.");int supports=new NtGeometry.Path(plan.points(),plan.settings()).stations.length*2;for(var existing:store.tunnels.values())if(!existing.id().equals(m.id()))supports+=new NtGeometry.Path(existing.plan().points(),existing.plan().settings()).stations.length*2;if(supports>768)NtTerrain.add(errors,"This dimension already uses its 768-support budget.");if(before==null&&store.tunnels.size()>=128)NtTerrain.add(errors,"This dimension already has 128 tunnels.");plan=new NtGeometry.Plan(plan.points(),plan.settings(),plan.lift(),plan.left(),plan.right(),errors);
   if(m.action()==NtRequest.PREVIEW){if(m.sequence()<=draft.sequence)return;draft.plan=plan;draft.sequence=m.sequence();draft.id=m.id();draft.revision=m.revision();draft.accepted=plan.points();preview(player,m,plan);return;}
   if(!plan.valid()||!plan.fingerprint().equals(m.fingerprint())){draft.plan=plan;preview(player,m,plan);throw new IllegalArgumentException(plan.valid()?"Terrain changed: review the updated preview, then build again.":plan.errors().get(0));}
   if(distance(player,plan.points())>32)throw new IllegalArgumentException("Move within 32 blocks of the route to build.");
   int[] cost=NtTerrain.cost(plan),old=before==null?new int[3]:NtTerrain.cost(before.plan()),paid=before==null?new int[3]:new int[]{before.iron(),before.string(),before.chains()},take=new int[3];for(int i=0;i<3;i++)take[i]=player.isCreative()?0:Math.max(0,cost[i]-old[i]);if(!canPay(player,take))throw new IllegalArgumentException("Not enough materials: "+costText(take));
   var built=new NtTunnel(before==null?UUID.randomUUID():before.id(),before==null?player.getUUID():before.owner(),store.next(),dimension,plan,paid[0]+take[0],paid[1]+take[1],paid[2]+take[2]);
   // All validation precedes the single server-thread mutation; revision check prevents repeated-click races.
   store.put(built);consume(player,take);store.undo.put(player.getUUID(),new NtStore.Undo(built.id(),built.revision(),before));store.setDirty();draft.plan=null;AddonNetwork.sendNt(player,new NtReply(NtReply.RESULT,m.sequence(),built.id(),dimension,"Tunnel built. "+(player.isCreative()?"Creative: no materials consumed.":"Paid "+costText(take)),built));
  }catch(IllegalArgumentException ex){result(player,m,ex.getMessage()==null?"Invalid tunnel request.":ex.getMessage());}
 }
 private static void preview(ServerPlayer p,NtRequest m,NtGeometry.Plan plan){var t=new NtTunnel(m.id()==null?new UUID(0,0):m.id(),p.getUUID(),m.revision(),p.serverLevel().dimension().location().toString(),plan,0,0,0);AddonNetwork.sendNt(p,new NtReply(NtReply.PREVIEW,m.sequence(),m.id(),t.dimension(),plan.valid()?previewCost(p,m,plan):plan.errors().get(0),t));}
 private static String previewCost(ServerPlayer p,NtRequest m,NtGeometry.Plan plan){int[] cost=NtTerrain.cost(plan);var previous=m.id()==null?null:NtStore.get(p.serverLevel()).tunnels.get(m.id());int[] old=previous==null?new int[3]:NtTerrain.cost(previous.plan());for(int i=0;i<3;i++)cost[i]=p.isCreative()?0:Math.max(0,cost[i]-old[i]);return "Ready. Materials to consume: "+costText(cost);}
 private static void result(ServerPlayer p,NtRequest m,String text){AddonNetwork.sendNt(p,new NtReply(NtReply.RESULT,m.sequence(),m.id(),p.serverLevel().dimension().location().toString(),text,null));}
 private static Vec3 physical(ServerPlayer p){Vec3 captured=PlayerDroneAnchorManager.getCapturedOriginalPosition(p);return captured==null?p.position():captured;}
 private static boolean owns(ServerPlayer p,NtTunnel t){return t.owner().equals(p.getUUID())||p.hasPermissions(2);}
 private static double distance(ServerPlayer p,NtTunnel t){return distance(p,t.plan().points());}
 private static double distance(ServerPlayer p,List<Vec3> points){double best=Double.POSITIVE_INFINITY;for(int i=1;i<points.size();i++){Vec3 a=points.get(i-1),d=points.get(i).subtract(a);double f=Math.max(0,Math.min(1,physical(p).subtract(a).dot(d)/d.lengthSqr()));best=Math.min(best,physical(p).distanceTo(a.add(d.scale(f))));}return best;}
 private static final Item[] MATERIALS={Items.IRON_INGOT,Items.STRING,Items.CHAIN};
 public static String costText(int[] c){return c[0]+" iron ingots, "+c[1]+" string, "+c[2]+" chains";}
 private static boolean canPay(ServerPlayer p,int[] cost){int[] have=new int[3];for(var stack:p.getInventory().items)for(int i=0;i<3;i++)if(stack.is(MATERIALS[i]))have[i]+=stack.getCount();for(int i=0;i<3;i++)if(have[i]<cost[i])return false;return true;}
 private static void consume(ServerPlayer p,int[] cost){for(int i=0;i<3;i++){int left=cost[i];for(var stack:p.getInventory().items)if(stack.is(MATERIALS[i])&&left>0){int n=Math.min(left,stack.getCount());stack.shrink(n);left-=n;}}p.getInventory().setChanged();p.containerMenu.broadcastChanges();}
 private static void refund(ServerPlayer p,int[] cost){for(int i=0;i<3;i++){int remaining=cost[i];while(remaining>0){int count=Math.min(64,remaining);var stack=new ItemStack(MATERIALS[i],count);if(!p.getInventory().add(stack)&&!stack.isEmpty())p.drop(stack,false);remaining-=count;}}p.getInventory().setChanged();p.containerMenu.broadcastChanges();}
 private static void undo(ServerPlayer p,NtStore s,NtRequest m){var u=s.undo.get(p.getUUID());NtTunnel current=u==null?null:s.tunnels.get(u.id());if(u==null||current==null||current.revision()!=u.expected()||!owns(p,current))throw new IllegalArgumentException("Undo unavailable: the last build has been changed or removed.");if(distance(p,current)>64)throw new IllegalArgumentException("Move within 64 blocks to undo.");var old=u.before();if(old!=null){var verified=NtTerrain.plan(p,old.plan().points(),old.plan().settings());if(!verified.valid()||!verified.fingerprint().equals(old.plan().fingerprint())||s.overlaps(current.id(),verified))throw new IllegalArgumentException("Undo would intersect changed terrain or another tunnel. Nothing changed.");}int[] give={Math.max(0,current.iron()-(old==null?0:old.iron())),Math.max(0,current.string()-(old==null?0:old.string())),Math.max(0,current.chains()-(old==null?0:old.chains()))};s.undo.remove(p.getUUID());if(old==null)s.remove(current.id());else s.put(old.revision(s.next()));s.setDirty();refund(p,give);result(p,m,"Last build undone. Later revisions were not touched.");}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post e){if(!(e.getEntity() instanceof ServerPlayer p)||p.tickCount%10!=0)return;var level=p.serverLevel();var dim=level.dimension().location().toString();var seen=WATCHED.computeIfAbsent(p.getUUID(),k->new HashMap<>());if(!dim.equals(DIMENSIONS.put(p.getUUID(),dim)))seen.clear();List<Vec3> centres=new ArrayList<>();centres.add(p.position());for(var stack:List.of(p.getMainHandItem(),p.getOffhandItem())){UUID linked=SbwCompat.getLinkedDroneUuid(stack);if(linked==null)linked=VatagMonitorTag.linked(stack);var camera=linked==null?null:level.getEntity(linked);if(camera!=null&&(VatagSessions.controlling(p,camera)||Rd01Sessions.controlling(p,camera)||Id01Sessions.controlling(p,camera)||SbwCompat.isUsingLinkedMonitorForDrone(p,camera)))centres.add(camera.position());}if(DroneJammerItem.isActiveJammerHeld(p)&&AddonConfig.portableFpvDetectorVideoEnabled()){UUID selected=PortableFpvDetectorServer.selectedForNt01(p);var remote=selected==null?null:level.getEntity(selected);if(remote!=null)centres.add(remote.position());}var store=NtStore.get(level);Map<UUID,Double> scores=new HashMap<>();for(var t:store.tunnels.values()){double best=Double.POSITIVE_INFINITY;for(Vec3 centre:centres)best=Math.min(best,distanceTo(t,centre,store));scores.put(t.id(),best);}var close=store.tunnels.values().stream().filter(t->scores.get(t.id())<192).sorted(Comparator.comparingDouble(t->scores.get(t.id()))).limit(32).toList();Set<UUID> near=new HashSet<>();for(var t:close)near.add(t.id());int sent=0;var iterator=seen.entrySet().iterator();while(iterator.hasNext()&&sent<4){var v=iterator.next();if(!near.contains(v.getKey())){AddonNetwork.sendNt(p,new NtReply(NtReply.REMOVE,0,v.getKey(),dim,"",null));iterator.remove();sent++;}}for(var t:close)if(sent<4&&!Objects.equals(seen.get(t.id()),t.revision())){AddonNetwork.sendNt(p,new NtReply(NtReply.UPSERT,0,t.id(),dim,"",t));seen.put(t.id(),t.revision());sent++;}}
 private static double distanceTo(NtTunnel t,Vec3 p,NtStore store){var bounds=store.bounds(t.id());double x=Math.max(bounds.minX,Math.min(bounds.maxX,p.x)),y=Math.max(bounds.minY,Math.min(bounds.maxY,p.y)),z=Math.max(bounds.minZ,Math.min(bounds.maxZ,p.z));return p.distanceTo(new Vec3(x,y,z));}
 @net.neoforged.bus.api.SubscribeEvent public static void logout(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent e){var id=e.getEntity().getUUID();DRAFTS.remove(id);WATCHED.remove(id);DIMENSIONS.remove(id);}
 @net.neoforged.bus.api.SubscribeEvent public static void stop(net.neoforged.neoforge.event.server.ServerStoppedEvent e){DRAFTS.clear();WATCHED.clear();DIMENSIONS.clear();NtCollision.clear();}
}
